std::string to_cstring(const std::vector<std::string>& vec) {
    if (vec.empty())
        return "";

    auto str_len = 0;
    for(auto& s: vec)
        str_len += s.size();

    auto total_size = str_len + (vec.size() * 3);
    std::string res;
    res.reserve(total_size);

    res += '{';
    res += vec[0];
    res += '}';

    for (size_t i = 1; i < vec.size(); i++) {
      res += ' ';
      res += '{';
      res += vec[i];
      res += '}';
    }

    return res;
}

const char* to_cstring(char* buf, size_t bufsize, const Font& font, int zoom) {
    snprintf(buf, bufsize, "{{%s} %d {{%s} {%s}}}", font.family(), zoom * font.size(), font.style(), font.weight());
    return buf;
}

